          break
        case TriggerOpTypes.DELETE:
          if (!targetIsArray) {
            push(depsMap.get(ITERATE_KEY))
            if (isMap(target)) {
              push(depsMap.get(MAP_KEY_ITERATE_KEY))
            }
          }
          break
        case TriggerOpTypes.SET:
          if (isMap(target)) {
            push(depsMap.get(ITERATE_KEY))
          }
          break
      }
    }
  }

  startBatch()
  for (const dep of deps) {
    if (__DEV__) {
      dep.trigger({
        target,
        type,
        key,
        newValue,
        oldValue,
        oldTarget,
      })
    } else {
      dep.trigger()
    }
  }
  endBatch()
}

