import { computed, ref, watch } from '@vue/runtime-test'

describe('tmp sync order', () => {
  it('ref sync watchers run in definition order', () => {
    const n = ref(0)
    const calls: string[] = []
    for (let i = 0; i < 5; i++) {
      watch(n, () => calls.push(String(i)), { flush: 'sync' })
    }
    n.value++
    expect(calls).toEqual(['0', '1', '2', '3', '4'])
  })
  it('computed sync watchers run in definition order', () => {
    const n = ref(0)
    const c = computed(() => n.value)
    const calls: string[] = []
    for (let i = 0; i < 5; i++) {
      watch(c, () => calls.push(String(i)), { flush: 'sync' })
    }
    n.value++
    expect(calls).toEqual(['0', '1', '2', '3', '4'])
  })
})
EOF
